    private FurnitureShapes() {}

    /** The boxes of an outline; a key the tool never wrote is a registration error, so it fails loudly. */
    public static List<double[]> boxes(String key) {
        List<double[]> boxes = SHAPES.get(key);
        if (boxes == null) {
            throw new IllegalStateException("no furniture outline '" + key + "' (run tools/furniture_models.py)");
        }
        return boxes;
    }

    private static void put(String key, double[]... boxes) {
        SHAPES.put(key, List.of(boxes));
    }

    private static double[] box(double x0, double y0, double z0, double x1, double y1, double z1) {
        return new double[]{x0, y0, z0, x1, y1, z1};
    }
